-- Isolated database only. All test records and removals roll back.
begin;
create temp table phase3_results(label text);
grant select,insert on phase3_results to authenticated,anon;
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is not true then raise exception 'FAILED: %',label;end if;insert into phase3_results values(label);end $$;
create function pg_temp.denied(q text,label text) returns void language plpgsql as $$declare blocked boolean:=false;begin begin execute q;exception when insufficient_privilege or raise_exception then blocked:=true;end;perform pg_temp.ok(blocked,label);end $$;
create function pg_temp.actor(n int,t int default 1) returns void language plpgsql as $$begin
 perform set_config('request.headers',jsonb_build_object('x-tenant-id','d1000000-0000-4000-8000-'||lpad(t::text,12,'0'))::text,true);
 perform set_config('request.jwt.claim.sub','d3000000-0000-4000-8000-'||lpad(n::text,12,'0'),true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub','d3000000-0000-4000-8000-'||lpad(n::text,12,'0'),'role','authenticated','session_id','d6000000-0000-4000-8000-'||lpad(n::text,12,'0'),'user_metadata','{"role":"admin"}'::jsonb)::text,true);
end $$;
insert into public.tenants values('d1000000-0000-4000-8000-000000000001','program-a','Program A',true),('d1000000-0000-4000-8000-000000000002','program-b','Program B',true);
insert into private.relationship_modules(tenant_id,enabled) select id,true from public.tenants where slug in('program-a','program-b');
insert into private.program_modules select id,true from public.tenants where slug in('program-a','program-b');
insert into auth.users(id,email,email_confirmed_at) select ('d3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'program-'||n||'@example.test',now() from generate_series(1,4)n;
insert into auth.sessions(id,user_id,created_at,updated_at) select ('d6000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('d3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,now(),now() from generate_series(1,4)n;
insert into private.path_people(tenant_id,id,user_id,display_name) select 'd1000000-0000-4000-8000-000000000001',('d4000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,('d3000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'Synthetic person '||n from generate_series(1,3)n;
insert into private.workflow_reviewers values('d1000000-0000-4000-8000-000000000001','d3000000-0000-4000-8000-000000000004','programs'),('d1000000-0000-4000-8000-000000000001','d3000000-0000-4000-8000-000000000004','privacy'),('d1000000-0000-4000-8000-000000000002','d3000000-0000-4000-8000-000000000002','programs');
insert into private.program_catalog(tenant_id,id,kind,title,description,status) values('d1000000-0000-4000-8000-000000000001','d5000000-0000-4000-8000-000000000001','learning','Private curriculum','SUBJECT_SENTINEL','approved'),('d1000000-0000-4000-8000-000000000001','d5000000-0000-4000-8000-000000000002','opportunity','Board example','SUBJECT_SENTINEL','approved');
set local role authenticated;select pg_temp.actor(1);
select public.program_command('{"type":"profile","payload":{"name":"SUBJECT_SENTINEL","background":"SUBJECT_SENTINEL"}}');
select pg_temp.ok(public.program_workspace()->'profile'->>'name'='SUBJECT_SENTINEL','Own profile persists');
select pg_temp.denied($q$select public.program_command('{"type":"profile","payload":{"name":"x","background":{"nested":"bad"}}}')$q$,'Direct RPC rejects malformed profile field types');
select public.program_command('{"type":"profile","payload":{"name":"SUBJECT_SENTINEL","linkedin":"https://www.linkedin.com/in/synthetic-example"}}');
select pg_temp.ok(public.program_workspace()->'profile'->>'linkedin'='https://www.linkedin.com/in/synthetic-example','Optional LinkedIn URL persists without network import');
select pg_temp.denied('select * from private.program_profiles','Clients cannot query private program profiles directly');
select pg_temp.denied($q$select public.program_command('{"type":"profile","user_id":"d3000000-0000-4000-8000-000000000002","payload":{"name":"forged"}}')$q$,'Cannot spoof profile owner');
select pg_temp.denied($q$select public.program_command('{"type":"review","id":"d5000000-0000-4000-8000-000000000002","state":"approved"}')$q$,'Participant cannot review opportunities');
select pg_temp.denied($q$select public.program_command('{"type":"interest","catalog_id":"d5000000-0000-4000-8000-000000000002","note":"x"}')$q$,'Interest requires explicit consent');
select public.program_command('{"type":"learning","catalog_id":"d5000000-0000-4000-8000-000000000001","state":"completed_self_reported","note":"SUBJECT_SENTINEL"}');
select public.program_command('{"type":"interest","catalog_id":"d5000000-0000-4000-8000-000000000002","consent":true,"note":"SUBJECT_SENTINEL"}');
select public.program_command('{"type":"outcome","catalog_id":"d5000000-0000-4000-8000-000000000002","note":"SUBJECT_SENTINEL"}');
select pg_temp.ok(jsonb_array_length(public.program_workspace()->'records')=3,'Learning interest and self-reported outcome persist');
select pg_temp.actor(2);
select pg_temp.ok(public.program_workspace()->'profile'='null'::jsonb and jsonb_array_length(public.program_workspace()->'records')=0,'Another participant sees no profile or private activity');
select pg_temp.denied($q$select public.program_command('{"type":"review","id":"d5000000-0000-4000-8000-000000000002","state":"approved"}')$q$,'Reviewer from another tenant has no authority here');
select public.program_command('{"type":"profile","payload":{"name":"Other participant","background":"Mentions SUBJECT_SENTINEL"}}');
select pg_temp.actor(1,2);select pg_temp.denied('select public.program_workspace()','No cross-organization workspace access');
select pg_temp.actor(2,2);select pg_temp.ok(jsonb_array_length(public.program_workspace()->'catalog')=0,'Other tenant reviewer sees no catalog from first tenant');
select pg_temp.denied($q$select public.program_command('{"type":"review","id":"d5000000-0000-4000-8000-000000000002","state":"approved"}')$q$,'Cross-tenant ID cannot be reviewed');
select pg_temp.actor(4);select pg_temp.ok(public.program_workspace()->'profile'='null'::jsonb,'Program reviewer does not receive participant profiles');
select pg_temp.actor(1);select set_config('test.delete3',public.path_request_deletion()::text,true);
select pg_temp.actor(4);select pg_temp.denied($q$select public.path_erase(current_setting('test.delete3')::uuid)$q$,'Deletion refuses unclassified program free text and JSON');
reset role;
-- Historical/operator-inserted nested JSON still must be covered by erasure.
update private.program_profiles set payload=payload||'{"historical":{"nested":"SUBJECT_SENTINEL"}}'::jsonb where tenant_id='d1000000-0000-4000-8000-000000000001';
do $$declare tab text;begin foreach tab in array array['program_profiles','program_catalog','program_records','program_events'] loop execute format('insert into private.personal_data_inventory(tenant_id,table_name,row_key,subjects) select tenant_id,$1,id::text,array[$2::uuid] from private.%I where tenant_id=$3::uuid',tab) using tab,'d3000000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000001';end loop;end $$;
set local role authenticated;select pg_temp.actor(4);select public.path_erase(current_setting('test.delete3')::uuid);
reset role;
select pg_temp.ok(not exists(select 1 from private.program_events where tenant_id='d1000000-0000-4000-8000-000000000001'),'Deletion removes historical civic notes, decisions and consent payloads');
select pg_temp.ok(not exists(select 1 from private.program_profiles where tenant_id='d1000000-0000-4000-8000-000000000001'),'Deletion covers own and other-person profile JSON mentioning subject');
select pg_temp.ok(not exists(select 1 from private.program_records where tenant_id='d1000000-0000-4000-8000-000000000001'),'Deletion removes learning interest and outcome notes');
select pg_temp.ok(not exists(select 1 from private.program_catalog where tenant_id='d1000000-0000-4000-8000-000000000001' and to_jsonb(program_catalog)::text like '%SUBJECT_SENTINEL%'),'Deletion minimizes catalog free text');
update private.program_modules set enabled=false where tenant_id='d1000000-0000-4000-8000-000000000002';
set local role authenticated;select pg_temp.actor(2,2);select pg_temp.denied('select public.program_workspace()','Disabled program fails closed');
select pg_temp.actor(4);select pg_temp.ok(public.program_workspace()->>'reviewer'='true','Other workspace remains available after disable');
reset role;
delete from private.program_modules where tenant_id='d1000000-0000-4000-8000-000000000002';
delete from private.workflow_reviewers where tenant_id='d1000000-0000-4000-8000-000000000002';
delete from private.relationship_modules where tenant_id='d1000000-0000-4000-8000-000000000002';
delete from public.tenants where id='d1000000-0000-4000-8000-000000000002';
set local role authenticated;select pg_temp.actor(4);select pg_temp.ok(public.program_workspace()->>'reviewer'='true','Removing second tenant leaves primary permissions and schema intact');
reset role;set local role anon;select pg_temp.denied('select public.program_workspace()','Anonymous program access denied');
reset role;
select pg_temp.ok((select bool_and(relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname in('program_profiles','program_records','program_catalog','program_modules')),'All program tables have RLS');
select jsonb_build_object('passed',count(*),'checks',jsonb_agg(label)) as phase3_result from phase3_results;
rollback;
